const LOTES = [{"codigo":"macaeprev-2024-enfermeiro","ano":2024,"orgao":"Instituto de Previdência Social do Município de Macaé — MACAEPREV","cargo":"Analista Previdenciário — Enfermagem, Tipo 1","urlProva":"https://conhecimento.fgv.br/sites/default/files/concursos/analista-previdenciario-especialidade-enfermagemcns202-tipo-1.pdf","urlGabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/ed.-2-macaeprev2024_recursos_gabarito_definitivo_compilado.pdf","itens":[{"numero":1,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"Leia a frase a seguir. Escreve-se a história para narrar e não para provar. Sobre a estruturação e significação dessa frase, assinale a afirmativa correta.","alternativas":["O termo “história” poderia ser adequadamente substituído por “estória”.","O termo “para narrar” equivale a “para que se narre”.","O conectivo e, na frase dada, tem valor de adição.","“Escreve-se” mostra sujeito indeterminado.","O conectivo indica valor de modo"],"correta":"B"},{"numero":2,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Leia com atenção o texto a seguir, incluído em um informe publicitário de www.planetasustentável.com.br. O que deve mudar no clima? Estimativas preliminares indicam que a elevação da temperatura global provocará um aumento da evaporação da água dos solos e alterações no balanço hídrico. Fenômenos que levariam, por exemplo, a uma redução do cultivo de plantas de clima temperado no Brasil. Ao mesmo tempo, haveria uma redução de geadas no sul, sudeste e sudoeste do país, o que beneficiaria culturas adaptadas ao clima tropical nessas áreas. Também são previstas modificações na circulação atmosférica próxima à superfície, o que impactaria o potencial de geração de energia eólica do Brasil, considerado um dos maiores do mundo. Sobre a estruturação ou a significação dos elementos desse texto, assinale a afirmativa correta.","alternativas":["O objetivo principal da campanha enunciada acima é promover mudanças de cultivo em alguns pontos do Brasil.","A consequência das alterações meteorológicas que mais afetariam a vida dos brasileiros é a que impacta o potencial de geração de energia eólica no país.","A construção de frases e parágrafos apresenta uma organização e estruturação clara e, por isso, a linguagem é de fácil compreensão, o que é adequado em um anúncio publicitário.","Na linha 4 do texto, a palavra fenômenos refere-se globalmente a estimativas preliminares, elevação da temperatura global, aumento da evaporação dos solos e alterações no balanço hídrico.","A expressão por exemplo, nas linhas 3 e 4, expressa o sentido de retificação"],"correta":"C"},{"numero":3,"disciplina":"Língua Portuguesa","assunto":"Coesão e Coerência","enunciado":"Os elementos de coesão estão destacados em todas as frases a seguir. Assinale o conector que tem seu valor semântico corretamente indicado.","alternativas":["Conforme o noticiário da noite, as reportagens do jornal paulista vão acrescentar novas informações à discussão. / semelhança.","As mudanças meteorológicas modificarão o sistema de plantio, por conseguinte o país poderá começar a produzir frutos diferentes. / explicação.","Todos os atletas participaram da competição, exceto os que já tinham sido eliminados nas provas anteriores. / ressalva.","A polícia chegou imediatamente, pegando os meliantes em flagrante delito. / duração de tempo.","Os prêmios serão possivelmente pagos ainda esta semana. / afirmação"],"correta":"C"},{"numero":4,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"As frases a seguir mantêm relação de sentido com a proteção ao meio ambiente, à exceção de uma. Assinale-a.","alternativas":["As pontes construídas sobre os rios levaram meses para ficarem prontas.","Os rios passaram a mostrar menos força no fluxo de água após a construção da barragem.","As árvores da região sofreram com a seca antecipada, mas só algumas morreram.","A água potável certamente será uma das maiores riquezas de um país, futuramente.","O uso de certos combustíveis deve ser proibido futuramente, em função do prejuízo que trazem ao ar"],"correta":"A"},{"numero":5,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Leia o texto descritivo a seguir. O dicionário era relativamente grosso, com uma capa de couro escura, coberta por uma folha amarela em que estavam escritas as informações sobre o tipo de livro que era. Sobre a descrição acima, assinale afirmativa adequada.","alternativas":["Os adjetivos empregados no texto mostram qualidades do objeto descrito.","A descrição do dicionário só abrange marcas externas da obra.","O texto mostra poucas informações sobre o livro em função das limitações provocadas pela localização do observador.","O observador valoriza o produto descrito por meio de opiniões positivas.","O objeto descrito segue, em sua descrição, o movimento do todo para as partes"],"correta":"B"},{"numero":6,"disciplina":"Língua Portuguesa","assunto":"Figuras de Linguagem e Vícios de Linguagem","enunciado":"Assinale a frase que mostra um jogo de palavras em sua construção.","alternativas":["Quem inventou o trabalho não tinha o que fazer.","Melhor do que roubar um banco é fundar um.","Apaixonar-se é criar uma religião que tem um deus falível.","Há dois tipos de esposas: a que arruma a casa e a que se arruma.","A melancolia é o prazer de estar triste."],"correta":"D"},{"numero":7,"disciplina":"Língua Portuguesa","assunto":"Pontuação","enunciado":"Assinale a frase em que todos os sinais de pontuação estão corretamente empregados.","alternativas":["A única pergunta idiota, é aquela que você não faz.","Se você está seguindo no rumo errado, lembre-se: de que Deus encheu a estrada de retornos.","As ideias geniais são aquelas, que nos espantamos de não ter tido, antes.","O que prevemos raramente ocorre: o que menos esperamos geralmente acontece.","Os prazeres são relâmpagos; os sofrimentos, séculos"],"correta":"E"},{"numero":8,"disciplina":"Língua Portuguesa","assunto":"Tempos, Modos e Vozes Verbais","enunciado":"Assinale a frase em que a passagem da voz ativa para a passiva com auxiliar foi feita de forma adequada.","alternativas":["A fúria provê as armas. / As armas são provindas pela fúria.","A paz é o tempo em que os políticos dizem tolices. / A paz é o tempo de as tolices serem ditas","Bons sentimentos jamais criam boas estratégias. / Boas estratégias jamais foram criadas por bons sentimentos.","A flecha dignifica o alvo. / O alvo é dignificado pela flecha.","Guerra implica baixas. / Baixas foram implicadas pela guerra"],"correta":"D"},{"numero":10,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Assinale a frase que se enquadra entre textos injuntivos.","alternativas":["Faça sempre o bem, não importa a quem.","Os cidadãos de um país podem mudá-lo.","Para encontrar a resposta certa você deve fazer a pergunta certa.","O verão é mais incômodo que o inverno.","Sempre haverá um conflito entre o bom e o ótimo."],"correta":"A"},{"numero":11,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Argumentação Lógica","enunciado":"Sabe-se, sobre as alturas de 5 mulheres, que: - Bianca tem 3 cm a menos que Alice; - Carla tem 3 cm a mais que Dalva; - Alice tem 20 cm a menos que Érica; - Bianca tem 1,57 m de altura. Com base nessas informações, é correto concluir que, entre as 5 mulheres,","alternativas":["Alice é a mais baixa.","Bianca é mais baixa que Érica.","Carla é mais alta que Alice.","Dalva é mais alta que Érica.","Érica é a mais alta"],"correta":"B"},{"numero":12,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Sequências e Padrões","enunciado":"Considere uma sequência infinita de números em que, a partir do 2º, cada termo corresponde ao triplo do termo que o antecede subtraído de 2 unidades. Se o 4º termo dessa sequência vale 82, então o 1º termo é um número","alternativas":["menor que 2,5.","maior que 2,5 e menor que 3,5.","maior que 3,5 e menor que 4,5.","maior que 4,5 e menor que 5,5.","maior que 5,5"],"correta":"C"},{"numero":14,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Análise Combinatória","enunciado":"Os seis elementos de uma matriz formada por 2 linhas e 3 colunas são {1, 2, 3, 4, 5 e 6}. As colunas são contadas da esquerda para a direita e as linhas, de cima para baixo. Sabe-se que: - a soma dos elementos da primeira coluna é 10; - a soma dos elementos da segunda coluna é 5; - a soma dos elementos da primeira linha é 8. O elemento que ocupa a posição correspondente à segunda linha e à terceira coluna é","alternativas":["1.","2.","3.","4.","5."],"correta":"E"},{"numero":15,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Proposições e Conectivos","enunciado":"Paulo, Ricardo, Sílvio e Tales deram, nessa ordem, as seguintes declarações: Paulo: “Eu sou professor”. Ricardo: “Paulo não é professor”. Sílvio: “Ricardo está mentindo”. Tales: “Sílvio falou a verdade”. A respeito dessas declarações, é possível que","alternativas":["todos estejam mentindo.","todos estejam falando a verdade.","Paulo e Ricardo estejam ambos mentindo.","Ricardo e Sílvio estejam ambos mentindo.","Silvio e Tales estejam ambos mentindo"],"correta":"E"},{"numero":16,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Conjuntos Numéricos","enunciado":"Um número inteiro positivo menor do que 100, deixa resto 6 quando dividido por 7, deixa resto 7 quando dividido por 8. Sendo assim, esse número é divisível por","alternativas":["17.","15.","13.","11.","10"],"correta":"D"},{"numero":17,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Conjuntos","enunciado":"Em uma pesquisa feita com N corredores amadores, constatou-se que 20 nunca correram uma meia-maratona, 15 correram pelo menos 3 meias-maratonas e 55 correram, no máximo, 2 meias- maratonas. N é um número","alternativas":["menor que 60.","maior que 60 e menor que 68.","maior que 68 e menor que 76.","maior que 76 e menor que 84.","maior que 84"],"correta":"C"},{"numero":18,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Argumentação Lógica","enunciado":"Entre Xavier, Vladimir e Zilmar, um deles tem cabelos castanhos, o outro tem cabelos ruivos e o terceiro, cabelos loiros. Os olhos também têm cores distintas sendo que um deles tem olhos castanhos, outro tem olhos verdes, e o terceiro, olhos azuis. Xavier não tem olhos azuis. Quem tem olhos verdes não possui cabelos loiros. Zilmar não tem cabelos e nem olhos castanhos. Quem tem cabelos castanhos também tem olhos azuis. Nesse caso, é correto afirmar que","alternativas":["Xavier tem olhos castanhos.","Xavier tem cabelos ruivos.","Vladimir tem olhos verdes.","Vladimir tem cabelos loiros.","Zilmar tem olhos azuis"],"correta":"A"},{"numero":19,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Regra de Três e Problemas Aritméticos","enunciado":"Cento e vinte canetas foram distribuídas pelas 5 gavetas de uma escrivaninha. Na 1ª gaveta, foram colocadas 3 canetas a mais do que na 2ª gaveta. Na 3ª gaveta, foram colocadas 3 canetas a menos do que na 4ª gaveta. Na 5ª gaveta, foram colocadas 3 canetas a mais do que na 1ª gaveta. Na 2ª gaveta, foram colocadas 9 canetas a menos do que na 3ª gaveta. Com base nessas informações, é correto afirmar que","alternativas":["nenhuma gaveta contém 30 canetas.","nenhuma gaveta contém 28 canetas.","alguma gaveta contém 26 canetas.","nenhuma gaveta contém 24 canetas","alguma gaveta contém 22 canetas"],"correta":"B"},{"numero":20,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Regra de Três e Problemas Aritméticos","enunciado":"Em uma modalidade esportiva, cada vez que um competidor qualquer vence seu adversário em uma partida, ele recebe 5 pontos por essa vitória. Quem sai derrotado de uma partida, perde 1 ponto. Se houver empate, ambos recebem 2 pontos. Disputando 4 partidas, um competidor pode totalizar","alternativas":["3 pontos negativos.","0 ponto.","12 pontos.","14 pontos.","18 pontos. Legislação Municipal"],"correta":"D"},{"numero":27,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Organização e Competências","enunciado":"De acordo com a Lei nº 8.080/1990, a organização de atendimento público específico e especializado para mulheres e vítimas de violência doméstica em geral, faz parte do seguinte dispositivo do SUS.","alternativas":["objetivos.","princípios.","atribuições.","competências.","metodologia"],"correta":"C"},{"numero":28,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"Acerca dos Requisitos de Boas Práticas de Funcionamento para os Serviços de Saúde, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Em serviços de saúde com mais de vinte trabalhadores é obrigatória a instituição de Comissão Interna de Prevenção de Acidentes – CIPA. ( ) O serviço de saúde deve garantir que todos os usuários recebam suporte imediato de vida quando necessário. ( ) O serviço de saúde deve estar inscrito e manter seus dados atualizados no Cadastro Nacional de Estabelecimentos de Saúde – CNES. As afirmativas são, respectivamente,","alternativas":["F – V – F.","V – F – V.","F – F – V.","V – V – V.","F – V – V."],"correta":"D"},{"numero":29,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"De acordo com as disposições acerca da segurança do paciente em serviços de saúde, a notificação dos eventos adversos deve ser realizada mensalmente pelo Núcleo de Segurança do Paciente (NCP), até","alternativas":["o 1º dia útil do mês subsequente ao mês de vigilância.","o 7º dia útil do mês subsequente ao mês de vigilância.","o 10º dia útil do mês subsequente ao mês de vigilância.","o 12º dia útil do mês subsequente ao mês de vigilância.","o 15º dia útil do mês subsequente ao mês de vigilância"],"correta":"E"},{"numero":30,"disciplina":"Legislação do SUS","assunto":"Direitos dos Usuários do SUS","enunciado":"Com base na Resolução CNS nº 553/2017, que atualiza a carta dos direitos e deveres da pessoa usuária da saúde, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A promoção e a proteção da saúde devem estar relacionadas com as condições sociais, culturais e econômicas das pessoas, incluídos aspectos como segurança alimentar e nutricional. ( ) Os serviços de saúde devem ser organizados segundo a demanda da população, e não limitados por produção ou quantidades de atendimento pré-determinados. ( ) O usuário tem direito a visita diária com duração máxima de uma hora, exceto nas unidades de internação de alta complexidade ou com restrições clínicas. As afirmativas são, respectivamente,","alternativas":["F – V – F.","V – V – F.","F – V – V.","V – F – V.","F – F – F"],"correta":"B"},{"numero":31,"disciplina":"Enfermagem","assunto":"Atenção Primária à Saúde","enunciado":"O Programa Nacional de Controle do Tabagismo é responsável por articular a Rede de tratamento do tabagismo no SUS. Uma das ações iniciais como parte do protocolo clínico para o tratamento dos pacientes é a realização do Teste de Fagerström. Esse teste tem como objetivo avaliar","alternativas":["o grau de dependência do paciente à nicotina.","o efeito nocivo do tabaco na saúde do paciente.","as comorbidades associadas ao uso do cigarro.","os fatores de risco modificáveis e não modificáveis.","o estado de saúde geral do paciente e suas limitações"],"correta":"A"},{"numero":32,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Organização e Competências","enunciado":"Com base nas disposições legais acerca do Sistema Único de Saúde, assinale a afirmativa correta.","alternativas":["As Comissões Intergestores Bipartite têm a finalidade de articular políticas e programas de interesse para a saúde, cuja execução envolva áreas não compreendidas no âmbito do Sistema Único de Saúde.","O Conselho de Saúde é um órgão com representação de vários segmentos sociais que tem a função de avaliar a situação de saúde e propor as diretrizes para a formulação da política de saúde nos níveis correspondentes.","Toda mulher tem o direito de ter um acompanhante maior de idade durante consultas, exames e procedimentos realizados nos serviços públicos de saúde, independentemente de notificação prévia.","O processo de planejamento da saúde deve ser integrado, descendente, sempre do nível federal até o local, compatibilizando-se as necessidades das políticas de saúde com a disponibilidade de recursos financeiros.","O atendimento na modalidade de telessaúde é restrito a algumas profissões da área da saúde e deve ser realizado sempre com o consentimento livre e informado do paciente, sendo vedado para os atendimentos de primeira consulta. Noções de Direito Previdenciário"],"correta":"C"},{"numero":33,"disciplina":"Legislação do SUS","assunto":"Constituição Federal - Saúde","enunciado":"De acordo com o Art. 194 da Constituição Federal de 1988, a seguridade social compreende um conjunto integrado de ações de iniciativa dos Poderes Públicos e da sociedade, destinadas a assegurar os direitos relativos à saúde, à previdência e à assistência social. Um dos princípios constitucionais da Seguridade Social é a diversidade da base de financiamento. Além das fontes normais de arrecadação, nada impede que outras sejam instituídas pela União, desde que o faça mediante","alternativas":["Lei Complementar.","Lei Ordinária.","Emenda Constitucional.","Medida Provisória.","Decreto Autônomo"],"correta":"A"},{"numero":46,"disciplina":"Enfermagem","assunto":"Processo de Enfermagem e SAE","enunciado":"No Diagnóstico de Enfermagem com base na taxonomia da NANDA, as influências que aumentam a vulnerabilidade de indivíduos, famílias, grupos ou comunidades a um evento não saudável são denominadas","alternativas":["fatores de risco.","condições associadas.","fatores relacionados.","populações em risco.","características definidoras"],"correta":"A"},{"numero":47,"disciplina":"Enfermagem","assunto":"Processo de Enfermagem e SAE","enunciado":"Na prática assistencial, quando o enfermeiro realiza intervenções, ações e atividades previstas no Plano Assistencial de Enfermagem ele está colocando em prática a seguinte etapa do Processo de Enfermagem:","alternativas":["evolução.","avaliação.","diagnóstico.","planejamento.","implementação"],"correta":"E"},{"numero":48,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Uma paciente adulta, sexo feminino, internada para realizar uma intervenção cirúrgica eletiva, apresentou os seguintes valores, entre outros, no hemograma: Hematócrito = 37%; Hemoglobina = 13 g/dL; Leucócitos = 5.100/mm³. Nesse caso é correto afirmar que","alternativas":["os três valores estão normais.","os três valores estão abaixo do normal.","o hematócrito está abaixo do normal e os leucócitos e a hemoglobina estão normais.","os leucócitos estão acima do normal e o hematócrito e a hemoglobina estão abaixo.","a hemoglobina está acima do normal, o hematócrito está abaixo do normal e os leucócitos estão normais"],"correta":"A"},{"numero":49,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"De acordo com as diretrizes atualizadas da American Heart Association, na assistência a um paciente com intoxicação por cianeto, o tratamento inicial recomendado é a administração de","alternativas":["Naloxona.","Flumazenil.","Azul de metileno.","Hidroxocobalamina.","Bicabornato de sódio"],"correta":"D"},{"numero":50,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Com base nas orientações da ANVISA para prevenção de infecção relacionada ao cateter umbilical arterial e venoso, assinale a afirmativa correta.","alternativas":["É contraindicado o uso de clorexidina alcoólica ou aquosa na assepsia do coto e da região periumbilical.","Recomenda-se não utilizar tintura de iodo pelo impacto sobre a glândula tireoide do neonato.","Recomenda-se aplicar pomada antimicrobiana tópica no sítio umbilical.","O cateter umbilical venoso deve ser mantido por, no máximo, 20 dias.","O cateter umbilical arterial deve ser mantido por, no máximo, 15 dias"],"correta":"B"},{"numero":51,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"Com base na classificação das drogas quimioterápicas de acordo com seu potencial de causar lesão de pele, assinale a opção que apresenta um quimioterápico classificado como vesicante.","alternativas":["Alcaloides da vinca.","Derivados da platina","Agentes alquilantes.","Anticorpos monoclonais","Inibidores da Topoisomerase I"],"correta":"A"},{"numero":52,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"De acordo com as recomendações do Ministério da Saúde, em crianças de seis meses a menores de 2 anos de idade, a Vacina COVID-19 deve ser administrada preferencialmente no","alternativas":["deltoide.","dorso glúteo.","reto femoral.","vasto lateral da coxa.","vasto medial da coxa"],"correta":"D"},{"numero":53,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"O uso da ventilação mecânica não invasiva (VMNI) tem demonstrado redução na incidência de pneumonia comparado com a ventilação mecânica invasiva. Contudo, existem algumas situações que contraindicam essa prática. Uma das contraindicações absolutas para o uso de VMNI é","alternativas":["cirurgia facial.","parada cardíaca.","alto risco de aspiração.","anastomose de esôfago recente.","obstrução de vias aéreas superiores"],"correta":"B"},{"numero":54,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Acerca das alterações do ritmo respiratório, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A Respiração de Cheyne-Stokes caracteriza-se por inspirações rápidas e amplas, intercaladas por expirações rápidas com pouca amplitude e curtos períodos de apneia. ( ) Na hipoventilação a frequência respiratória é anormalmente baixa e a profundidade de ventilação é deprimida. ( ) A respiração de Biot, também conhecida como respiração atáxica, é caracterizada por um momento de apneia, seguida de movimentos respiratórios irregulares. As afirmativas são respectivamente:","alternativas":["V – F – F.","F – V – V.","V – V – V.","F – F – F.","V – F – V"],"correta":"B"},{"numero":55,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Com base na classificação dos distúrbios hipertensivos na gestação e considerando os critérios de medição, um aspecto que caracteriza a Hipertensão Gestacional é","alternativas":["presença de PAD ≥90 mmHg com proteinúria.","ocorrência antes da 20ª semana de gestação.","presença de PAS ≥138 mmHg com sinais de gravidade.","história de hipertensão arterial antes da gestação.","presença de PAS ≥140 mmHg sem sinais de gravidade."],"correta":"E"},{"numero":56,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"Durante o atendimento a um paciente com dengue, o profissional de enfermagem identificou um sinal de alarme. Entre esses sinais está","alternativas":["a cefaleia intensa.","o sangramento grave.","a hipotensão postural.","o pulso filiforme ou dicrótico.","a febre alta e persistente"],"correta":"C"},{"numero":57,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Com base na Diretriz de Assistência ao Parto Normal, assinale a afirmativa correta.","alternativas":["A profilaxia antibiótica para Ruptura Prematura de Membranas no termo é recomendada em mulheres com período de latência superior a 12 horas.","A eliminação de mecônio durante o trabalho de parto, de forma isolada, é indicação de cesariana.","A fase latente do primeiro período do parto é caracterizada por um grau substancial de apagamento cervical e dilatação mais rápida.","Recomenda-se a pelvimetria clínica de rotina na admissão de gestantes saudáveis de risco habitual.","No primeiro período do parto de parturientes de risco habitual deve-se registrar a frequência cardíaca materna de 2 em 2 horas"],"correta":"A"},{"numero":58,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Em agosto de 2024 a Organização Mundial de Saúde voltou a declarar a mpox como uma emergência de saúde pública global. Com base nas definições e orientações do Ministério da Saúde relacionadas a essa doença, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa ( ) A mpox é caracterizada por lesões profundas e bem circunscritas cuja progressão se dá através de estágios sequenciais específicos (máculas, pápulas, vesículas, pústulas e crostas). ( ) Entre os critérios de definição de caso suspeito está a exposição prolongada, sem proteção respiratória, com caso provável ou confirmado de mpox nos 35 dias anteriores ao início dos sinais e sintomas. ( ) A vacinação pós exposição é recomendada para pessoas que tiveram contato direto com fluidos e secreções corporais de pessoas suspeitas, prováveis ou confirmadas para mpox, cuja exposição seja classificada como de alto ou médio risco As afirmativas são, respectivamente,","alternativas":["V – V – V.","F – F – V.","V –F – V.","F – V – F.","F – F – F"],"correta":"C"},{"numero":59,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"Na assistência ao recém-nascido, entre os sinais avaliados na escala de Apgar estão","alternativas":["cor da pele e saturação de O2.","pressão de pulso e débito urinário.","pressão arterial e frequência respiratória.","esforço respiratório e perímetro cefálico.","tônus muscular e irritabilidade reflexa"],"correta":"E"},{"numero":60,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Na ventilação mecânica invasiva, a quantidade de ar ofertada pelo ventilador a cada ciclo ventilatório é denominada","alternativas":["fluxo inspiratório.","volume corrente.","pressão de platô.","fração inspirada de oxigênio.","pressão expiratória final positiva"],"correta":"B"},{"numero":61,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Na avaliação do comprometimento neurológico de um paciente por intermédio da escala de coma de Glasgow, foi observada uma resposta motora com extensão anormal por descerebração. Assinale a opção que apresenta uma característica dessa resposta.","alternativas":["Extensão plantar.","Rotação interna das pernas.","Cotovelos em extensão rígida.","Braços e mãos em posição de C.","Cotovelos, punhos e dedos fletidos"],"correta":"C"},{"numero":62,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um paciente deu entrada em uma unidade da saúde apresentado dor torácica que, após avaliação, foi classificada como dor definitivamente anginosa. Com base nos critérios de caracterizarão da dor torácica e angina, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa ( ) O desconforto da dor anginosa geralmente é descrito com pressão, aperto ou peso no tórax, próximo à região do esterno. ( ) Assim como a dor anginosa, a dor não anginosa também pode ser precipitada por esforço, porém não é atenuada por nitratos. ( ) O desconforto anginoso estável é mais comum em pessoas do sexo masculino acima de 65 anos e tem duração maior que 15 minutos. As afirmativas são respectivamente","alternativas":["F – V – F.","V – V – V.","F – F – F.","V – F – F.","F – V – V"],"correta":"D"},{"numero":63,"disciplina":"Enfermagem","assunto":"Centro de Material e Esterilização (CME)","enunciado":"O reprocessamento de materiais requer o monitoramento através de testes e indicadores químicos e biológicos. Nesse sentido, assinale a opção que apresenta produtos para a saúde cuja carga só deve ser liberada para uso após leitura negativa de um indicador biológico.","alternativas":["Produtos implantáveis.","Ureterorrenoscópios flexíveis.","Instrumentais de vídeo cirurgia.","Produtos críticos de conformação complexa.","Produtos com lúmen superior a cinco milímetros."],"correta":"A"},{"numero":64,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"De acordo com as disposições do Ministério da Saúde e da Sociedade Brasileira de Pediatria, assinale a opção que indica um fator de risco para desenvolvimento de hiperbilirrubinemia significante em RN > 35 semanas de idade gestacional.","alternativas":["Mãe diabética.","Sexo feminino.","Peso ao nascer < 3000g.","Icterícia após 48 horas do nascimento.","Irmão com histórico de icterícia neonatal, com ou sem necessidade de tratamento"],"correta":"A"},{"numero":65,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Com base nas recomendações do Ministério da Saúde acerca do Protocolo Clínico e Diretrizes Terapêuticas para Profilaxia Pós Exposição de Risco (PEP) à Infecção pelo HIV, IST e Hepatites Virais, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa ( ) Entre os materiais biológicos com risco de transmissão do HIV estão líquido amniótico, secreções nasais, urina e sêmen. ( ) A PEP está contraindicada nos casos em que o teste rápido para HIV da pessoa exposta tenha resultado não reagente (TR1 não reagente). ( ) Recomenda-se imunizar todas as pessoas expostas não previamente vacinadas, ou sem documentação de vacinação prévia, e sem indícios de infecção por HBV (HBsAg não reagente), independentemente da idade. As afirmativas são respectivamente:","alternativas":["V – F – V.","F – F – V.","V – V – F.","F – V – F.","V – V – V"],"correta":"B"},{"numero":66,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um parâmetro a ser mantido nos cuidados pós-PCR de um paciente adulto é","alternativas":["PaCO2 menor que 35mmHg.","PaCO2 maior que 45mmHg.","saturação de O2 acima de 98%.","pressão arterial média > 65 mmHg.","pressão arterial sistólica < 90 mmHg"],"correta":"D"},{"numero":67,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"O Método Canguru é um dos modelos que compõem o Programa de Humanização no Pré-Natal e Nascimento. Acerca desse método, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa ( ) O Método Canguru é um modelo de assistência ao recém- nascido prematuro e sua família, internado na Unidade de Tratamento Intensivo Neonatal. ( ) Um dos pilares do Método Canguru é o estímulo ao aleitamento materno, incentivando o contato precoce e a presença constante da mãe junto ao recém-nascido. ( ) A posição canguru consiste em manter o recém-nascido de baixo peso em contato pele a pele, na posição vertical, junto ao peito dos pais. As afirmativas são, respectivamente,","alternativas":["V – V – F.","F – F – F.","V – F – V.","F – V – F.","V – V – V"],"correta":"E"},{"numero":68,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Assinale a opção que apresenta um fator de risco para complicações em pacientes com síndrome gripal.","alternativas":["Adultos ≥ 55 anos.","Crianças < 10 anos.","Idosos com hanseníase em tratamento.","Gestantes em qualquer idade gestacional.","Puérperas até quatro semanas após o parto"],"correta":"D"},{"numero":69,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Um paciente adulto, com suspeita de sífilis, apresentou manchas no corpo (que não coçam), incluindo palmas das mãos e plantas dos pés, além de febre, mal-estar, dor de cabeça e ínguas pelo corpo. De acordo com as manifestações clínicas apresentadas esse paciente apresenta sífilis","alternativas":["primária.","secundária.","terciária.","latente tardia.","latente recente"],"correta":"B"},{"numero":70,"disciplina":"Enfermagem","assunto":"Ética e Legislação em Enfermagem","enunciado":"Com base nas disposições do Código de Ética de Enfermagem, analise as afirmativas a seguir: I. É proibido ao profissional de Enfermagem executar procedimentos ou participar da assistência à saúde sem o consentimento formal da pessoa ou de seu representante legal, exceto em iminente risco de morte. II. São consideradas infrações leves aquelas que ofendem a integridade física, mental ou moral de qualquer pessoa, sem causar debilidade. III. Em casos específicos, o enfermeiro pode delegar atribuições dos profissionais de enfermagem, previstas na legislação, para acompanhantes e/ou responsáveis pelo paciente. É correto o que se afirma em","alternativas":["I, II e III.","I, apenas.","II, apenas.","I e II, apenas.","II e III, apenas."],"correta":"D"}]},{"codigo":"aleto-2024-enfermeiro","ano":2024,"orgao":"Assembleia Legislativa do Estado do Tocantins","cargo":"Analista Legislativo — Enfermagem, Tipo 1","urlProva":"https://conhecimento.fgv.br/sites/default/files/concursos/analista-legislativo-enfermagemcns111-tipo-1.pdf","urlGabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitivo-policial-legislativo-ii-tecnico-legislativo-e-analista-legislativo_dsa1c.pdf","itens":[{"numero":1,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Observe o seguinte texto: Quando entrei no terrível vagão, ele estava ocupado por duas pessoas. Uma, dobrada, coberta, dormia profundamente. A coberta superior estava manchada, de fundo amarelado, como pele de leopardo. Vendem -se muitas mantas assim nas lojas de artigos de viagens, mas pude notar logo depois que se tratava realmente da pele de um animal selvagem; do mesmo modo, o boné da pessoa adormecida me pareceu ser de feltro branco bastante delicado. O outro viajante, uma aparência s impática, parecia ter passado dos trinta anos e mostrava -se como figura insignificante que passa confortavelmente as noites em estradas de ferro. Nesse fragmento textual, para criar sinais de história realista e verdadeira, o narrador apela para a seguinte estratégia:","alternativas":["seleciona uma situação banal da qual não precisa fornecer muitos detalhes, exatamente por sua banalidade.","fornece algumas marcas caracterizadoras dos dois personagens presentes no texto, destacando sua banalidade.","indica traços descritivos do ambiente, mostrando -o como se nada houvesse nele de excepcional.","mostra detalhes variados e bastante pitorescos dos objetos descritos.","dá ao leitor informações sobre personagens e ambiente, mostrando-os como bastante conhecidos do narrador"],"correta":"B"},{"numero":2,"disciplina":"Língua Portuguesa","assunto":"Classes de Palavras","enunciado":"Assinale a frase que mostra a palavra mais numa classe gramatical diferente das demais.","alternativas":["O mercado está prisioneiro de mais um círculo vicioso: piora porque piorou e porque piorou, piora.","Os ingleses conquistaram o mundo po rque não aguentavam mais a própria cozinha.","Quanto mais vejo o estrangeiro, mais amo a minha pátria.","Não é mais possível aprender tudo de cor. Um homem instruído não é mais o homem que sabe muitas coisas; é o homem que sabe onde buscar informações.","Muda-se mais facilmente de religião do que de café"],"correta":"A"},{"numero":3,"disciplina":"Língua Portuguesa","assunto":"Coordenação e Subordinação","enunciado":"As frases a seguir mostram termos ligados pela conjunção OU. Assinale a frase em que essa conjunção mantém o valor de alternativa (e não de adição).","alternativas":["João ou Pedro deve ser eleito presidente da empresa.","A alegria ou a tristeza fazem parte da vida.","Inglês ou francês são idiomas falados pelos turistas","Os clientes leem livros ou revistas enquanto esperam.","Vasco ou Flamengo são times de longa tradição"],"correta":"A"},{"numero":4,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"Um guitarrista americano produziu o seguinte pensamento: O crítico de rock é alguém que não sabe escrever, entrevistando gente que não sabe falar, para gente que não sabe ler. Sobre a estruturação ou a significação desse pequeno texto, assinale a afirmativa incorreta.","alternativas":["O termo “de rock” funciona como complemento nominal do termo anterior.","Todos os elementos da cadeia comunicativa citados no texto são marcados pela ignorância.","O pensamento acima revela um preconceito fortíssimo contra os amantes de rock.","A opinião expressa no texto pode advir da experiência pessoal do autor, já que se trata de um guitarrista.","A injustiça desse texto provém de ser uma opinião fundamentada em uma autoridade duvidosa"],"correta":"E"},{"numero":5,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"John Steinbeck, prêmio Nobel, declarou o seguinte: O homem é o único animal que bebe sem ter sede, come sem ter fome e fala sem ter nada a dizer. Em relação ao significado e à estruturação desse peque no texto, assinale a afirmativa incorreta.","alternativas":["A frase ficaria mais enfática se invertêssemos a posição do termo inicial: O único animal que bebe sem ter sede, come sem ter fome e fala sem ter nada a dizer é o homem.","A inversão de alguns segmentos do texto em nada modificaria o sentido da frase: O homem é o único animal que come sem ter fome, bebe sem ter sede e fala sem ter nada a dizer.","Os segmentos finais do texto mostram preocupação com rigoroso paralelismo sintático.","Segundo a opinião do au tor do texto, a marca principal do homem é a irracionalidade.","Nem todas as ações citadas como marcas humanas estão presentes, por oposição, nos outros animais"],"correta":"C"},{"numero":6,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"Assinale a frase que não expressa uma noção de tempo abstrato.","alternativas":["Nas asas do tempo, a tristeza voa.","Quem mata o tempo não é assassino, é suicida.","O tempo perdido não se encontra nunca mais.","O tempo é o melhor professor. Infelizmente, ele mata todos os seus estudantes","O tempo gasto na viagem foi de duas horas"],"correta":"E"},{"numero":7,"disciplina":"Língua Portuguesa","assunto":"Crase","enunciado":"Assinale a frase em que a utilização do acento grave indicativo da crase é realizada de forma errada.","alternativas":["Jamais alguém se arrependeu de ter -se acostumado à madrugar e à ter-se casado jovem.","Tempo é o suspiro de adeus do sol à terra.","Saio todos os dias às cinco horas e não permito que o meu trabalho interfira no meu jogo de tênis.","O momento de extrair uma lição da história está sempre à mão para os sábios.","Quando assumi, quatro anos atrás, estávamos à beira do precipício."],"correta":"A"},{"numero":10,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"Assinale a opção que mostra uma impropriedade léxica, ou seja, um emprego inadequado da expressão “cerca de”.","alternativas":["Havia cerca de três dúzias de convidados no final da festa.","Chegaram cerca de 100 cartas no mesmo dia.","Cerca de 18 lojas fecharam as portas mais cedo.","Os cantores receberam cerca de uma centena de convites.","A plantação produziu cerca de uma tonelada de legumes"],"correta":"C"},{"numero":11,"disciplina":"Língua Portuguesa","assunto":"Estrutura e Formação de Palavras","enunciado":"Muitas palavras portuguesas mostram o prefixo A - sem qualquer valor semântico, sendo equivalentes ao mesmo vocábulo sem esse prefixo. Assinale a palavra a seguir que exemplifica esse A protético.","alternativas":["amostrar","abraçar","atenuar","aguardar","aparar"],"correta":"A"},{"numero":12,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Observe o seguinte texto: A felicidade depende da habilidade que tenhamos naquelas atividades que consideramos importantes: somente se lhes damos um real valor aos pequenos detalhes cotidianos, poderemos ter instantes felizes. A felicidade absoluta não existe, e já que só podemos acessar os pequenos detalhes daquilo que nos interessa, devemos contentar -nos com isso. Por isso, a infelicidade é um sinal claro de nossa incompetência na arte de viver. Sobre a estrutura e a significação desse texto, assinale a afirmativa inadequada.","alternativas":["O tema do texto gira em torno do que consiste a felicidade e o que viria a ser o seu oposto.","A afirmação de que “A felicidade absoluta não existe” é de cunho pessoal do autor do texto, representando uma opinião.","O raciocínio utilizado na estruturação argumentativa é do tipo dedutivo.","O conector “Por isso” mostra a preocupação com o caráter lógico da argumentação.","A tese do texto é a de que a infelic idade é fruto de nossa incompetência na arte de viver. Raciocínio Lógico Matemático"],"correta":"E"},{"numero":13,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Regra de Três e Problemas Aritméticos","enunciado":"Certo programa de rádio tem 1 hora e 55 minutos de duração. A partir do momento em que o programa é iniciado, há blocos temáticos de 7 minu tos intercalados por blocos de propagandas de 2 minutos. Em todos os blocos de propaganda, ouve -se o comercial do restaurante R, que sempre dura 18 segundos. Se o programa começa e termina com um bloco temático, então, o tempo total do programa dedicado a o anúncio do restaurante R é","alternativas":["3 minutos e 54 segundos.","3 minutos e 36 segundos.","3 minutos e 18 segundos.","3 minutos.","2 minutos e 48 segundos"],"correta":"B"},{"numero":14,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Regra de Três e Problemas Aritméticos","enunciado":"A linha de produção de certa fábrica produz 1100 latas de sardinhas a cada hora. Certo dia, por um defeito de calibragem do sistema, entre 13h e 14h, o volume de produção foi reduzido em 30% durante exatos 12 minutos. A quantidade de latas de sardinhas produzidas no intervalo supracitado foi","alternativas":["946.","964.","1022.","1034.","1046"],"correta":"D"},{"numero":15,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Argumentação Lógica","enunciado":"Marcelo está parado de frente para uma das paredes de uma sala quadrada. Nesta posição, ele está a 1m e 20cm da parede que se encontra à sua direita e a 1m e 70cm da parede que está às suas costas. Ele, então, se desloca parale lamente às paredes da sala sendo 40cm para a frente e 80cm para a direita. Nessa nova posição, ele passou a distar 1m e 90cm da parede que antes estava à sua esquerda. Desprezando-se as dimensões de Marcelo, a sua atual distância à parede que, antes dos movimentos, estava à sua frente, é","alternativas":["20cm.","30cm.","40cm.","50cm.","60cm."],"correta":"A"},{"numero":16,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Probabilidade","enunciado":"Um dado é dito comum quando tem a forma de um cubo e suas 6 faces são numeradas de 1 a 6, de tal forma que a soma dos números estampados em faces opostas , quaisquer que sejam elas, sempre somam 7. Quando um dado comum é lançado, diz -se que o resultado do lançamento é o número estampado na face voltada para cima. Um dado foi lançado 3 vezes seguidas. Se o produto dos resultados obtidos nos lançamentos vale 75, a soma desses resultados é igual a","alternativas":["12.","13.","14.","15.","16"],"correta":"B"},{"numero":17,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Sequências e Padrões","enunciado":"Em certo ano, o dia 1º de agosto cai em um domingo. Logo, o dia 1º de novembro cairá em","alternativas":["um sábado.","um domingo.","uma segunda-feira.","uma quarta-feira.","uma sexta-feira"],"correta":"C"},{"numero":18,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Proposições e Conectivos","enunciado":"Considere a seguinte proposição condicional: Se todos os alunos da Escola Aristarco gostam de matemática, então, ao menos um deles ganha medalha na Olimpíada Nacional de Matemática. Se essa proposição é verdadeira, é correto afirmar que","alternativas":["se nenhum dos alunos da Escola Aristarco gosta de Matemática, então nenhum deles ganha medalha na Olimpíada Nacional de Matemática.","se todos os alunos da Escola Aristarco ganham medalha na Olimpíada Nacional de Ma temática, então, todos esses alunos gostam de Matemática.","se algum aluno da Escola Aristarco ganha medalha na Olimpíada Nacional de Matemática, então todos esses alunos gostam de Matemática.","se nenhum aluno da Escola Aristarco ganha medalha na Olimpíada Nacional de Matemática, então nenhum desses alunos gosta de Matemática.","se nenhum aluno da Escola Aristarco ganha medalha na Olimpíada Nacional de Matemática, então algum desses alunos não gosta de Matemática"],"correta":"E"},{"numero":19,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Análise Combinatória","enunciado":"Em uma caixa, há muitas canetas esferográficas. Classificadas conforme a cor, elas podem ser azuis, vermelhas ou pretas. Classificadas quanto à espessura da esfera, elas podem ser de ponta fina ou de ponta grossa. Metade das canetas vermelhas tem a ponta grossa. A quantida de total de canetas pretas é igual à quantidade total de canetas vermelhas. Entre as canetas de ponta grossa, a quantidade de azuis é igual à de pretas. A quantidade de canetas azuis com ponta fina é o dobro da quantidade de canetas pretas de ponta grossa. Se, nessa caixa, 18 são azuis e 20 têm ponta grossa, então a quantidade total de canetas na caixa é","alternativas":["30.","40.","48.","50.","52"],"correta":"D"},{"numero":20,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Razão, Proporção e Porcentagem","enunciado":"Tucídides possuía uma dívida e, em vez de quitá -la, pagou apenas 20% do seu valor, deixando o restante para ser quitado em data futura, com acréscimo de 12% a título de juros sobre o saldo devedor. No ato de quitação, Tucídides pagou R$2.329,60. Logo, o valor original da dívida é o resultado da seguinte expressão:","alternativas":["2.329,60 x 0,88 – 20","2.329,60 0,88 x 1,20","2.329,60 1,12 x 1,20","2.329,60 1,12×1,20","2.329,60 1,12×0,8"],"correta":"E"},{"numero":21,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Razão, Proporção e Porcentagem","enunciado":"As filhas de Nepomuceno têm 5 e 9 anos de idade. Ele dividirá R$420,00 entre elas de forma inversamente proporcional às suas idades. Logo","alternativas":["a mais nova receberá R$120,00 a mais que a mais velha.","a mais nova receberá R$150,00 a mais que a mais velha.","a mais nova receberá R$270,00 a mais que a mais velha.","a mais velha receberá R$120,00 a mais que a mais nova.","a mais velha receberá R$150,00 a mais que a mais nova"],"correta":"A"},{"numero":22,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Equivalências e Negações","enunciado":"A negação da proposição: Se 𝑦 ≠ 0, então 𝑥 > 2 e 𝑥 ≤ 5 é dada por","alternativas":["Se 𝑦 = 0, então 𝑥 > 2 e 𝑥 ≤ 5","Se 𝑦 = 0, então 𝑥 < 2 ou 𝑥 ≥ 5","𝑦 = 0 e 𝑥 ≤ 2 ou 𝑥 > 5","𝑦 ≠ 0 e 𝑥 ≤ 2 ou 𝑥 > 5","𝑦 ≠ 0 e 𝑥 ≤ 2 e 𝑥 > 5 Atualidades"],"correta":"D"},{"numero":41,"disciplina":"Legislação do SUS","assunto":"Redes de Atenção à Saúde","enunciado":"A organização dos serviços de saúde em atenção primária, secundária e terciária (níveis crescentes de complexidade) visando disponibilizar a assistência requerida para cada caso, diz respeito ao seguinte princípio do SUS:","alternativas":["Equidade.","Universalidade.","Descentralização.","Regionalização.","Hierarquização"],"correta":"E"},{"numero":42,"disciplina":"Legislação do SUS","assunto":"Decreto 7.508/2011","enunciado":"De acordo com as disposições do Decreto nº 7.508/11, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O acordo de colaboração entre os entes federativos para a organização da rede interfederativa de atenção à saúde deve ser firmado por meio de Contrato Organizativo da Ação Pública da Saúde. ( ) O planejamento da saúde em âmbito estadual deve ser realizado de maneira regionalizada, a partir das necessidades dos Municípios, considerando o estabelecimento de metas de saúde. ( ) Entre as Portas de Entrada às ações e aos serviços de saúde nas Redes de Atenção à Saúde estão os serviços de Atenção Primária e os Ambulatórios de Especialidades. As afirmativas são, respectivamente,","alternativas":["V – F – V.","F – F – F.","V – V – F.","F – V – F.","V – V – V"],"correta":"C"},{"numero":43,"disciplina":"Legislação do SUS","assunto":"Lei 8.080/1990 - Organização e Competências","enunciado":"Considerando as disposições da Lei nº 8.080/90 acerca da telessaúde, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Entre os princípios que devem ser observados no exercício da telessaúde estão a assistência segura e com qualidade e a confidencialidade dos dados. ( ) Ao recusar o atendimento na modalidade telessaúde o paciente abre mão da possibilidade d e atendimento presencial. ( ) Compete aos Conselhos Federais de fiscalização do exercício profissional a normatização ética relativa à prestação dos serviços na modalidade telessaúde. As afirmativas são, respectivamente,","alternativas":["V – V – F.","F – V – F.","V – V – V.","F – F – F.","V – F – V"],"correta":"E"},{"numero":44,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Assinale a opção que corresponde a um tipo de estudo epidemiológico experimental.","alternativas":["Coorte.","Ecológico.","Caso-controle.","Transversal.","Ensaio de campo"],"correta":"E"},{"numero":45,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Com base nas diretrizes de atendimento a pacientes adultos e pediátricos em parada cardiorrespiratória, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Recomenda-se o uso rotineiro de pressão cricoide durante a intubação endotraqueal de pacientes pediátricos. ( ) Na Cadeia de Sobrevivência da AHA para adultos em parada cardiorrespiratória extra hospitalar – PCREH, após o acionamento do serviço médico de emergência deve -se iniciar a RCP de alta qualidade. ( ) Um dos ritmos cardíacos chocáveis em uma parada cardiorrespiratória é a Taquicardia Ventricular Sem Pulso (TVSP). As afirmativas são, respectivamente,","alternativas":["F – V – V.","V – V – V.","F – V – F.","V – F – V.","V – F – F"],"correta":"A"},{"numero":46,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um paciente adulto internado com síndrome gripal apresenta sinais e sintomas de Síndrome Respiratória Aguda Grave. Entre esses sintomas está saturação de oxigênio em ar ambiente abaixo de","alternativas":["95%.","96%.","97%.","98%.","99%"],"correta":"A"},{"numero":47,"disciplina":"Enfermagem","assunto":"Hipertensão Arterial","enunciado":"De acordo com as definições de Hipertensão Arterial Resistente e Refratária, previstas nas Diretrizes Brasileiras de Hipertensão Arterial, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Hipertensão Arterial Resistente (HAR) é de finida como a PA de consultório que permanece com valores ≥139/90mmHg, com o uso de duas ou mais classes de fármacos anti - hipertensivos. ( ) Quando o paciente necessita do uso de quatro ou mais fármacos anti -hipertensivos para alcançar o controle da PA, ele também é considerado um hipertenso resistente, porém controlado. ( ) Para definir a Hipertensão Arterial como Refratária é necessário que o paciente esteja em uso de três ou mais fármacos anti-hipertensivos com ações sinérgicas e em doses máximas preconizadas. As afirmativas são, respectivamente,","alternativas":["V – V – V.","F – F – F.","V – F – V.","F – V – F.","V – V – F."],"correta":"D"},{"numero":48,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Considerando as especificidades acerca das Hepatites Virais, analise as afirmativas a seguir. I - A imunidade para a hepatite E pode ser conferida indiretamente, por meio da vacina contra a hepatite B. II – O período prodrômico da hepatite aguda ocorre após o período de incubação do agente etiológico e anteriormente ao aparecimento da icterícia. III – Hepatite fulmina nte é o termo utilizado para designar a insuficiência hepática aguda, caracterizada pelo surgimento de icterícia, coagulopatia e encefalopatia hepática em um intervalo de até oito semanas. Está correto o que se afirma em","alternativas":["I, apenas.","II, apenas.","I e II, apenas.","II e III, apenas.","I, II e III"],"correta":"D"},{"numero":49,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Com base nas recomendações do Ministério da Saúde acerca do esquema terapêutico da Malária, a primaquina é contraindicada no tratamento de crianças menores de","alternativas":["6 meses.","9 meses.","12 meses.","2 anos.","5 anos"],"correta":"A"},{"numero":50,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Durante a avaliação de um paciente, foi identificada anisocoria. Essa alteração pupilar é caracterizada por","alternativas":["pupilas com forma anormal.","pupilas com tamanhos diferentes.","diminuição do tamanho pupilar abaixo de 2mm.","dilatação da pupila com reflexo fotomotor negativo.","dilatação da pupila com reflexo fotomotor positivo"],"correta":"B"},{"numero":51,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"De acordo com o Calendário de Vacinação da Criança do Ministério da Saúde, o intervalo mínimo recomendado para administração da segunda dose da Vacina COVID 19 é de","alternativas":["duas semanas após 1ª dose.","três semanas após 1ª dose.","quatro semanas após 1ª dose.","seis semanas após 1ª dose.","oito semanas após 1ª dose"],"correta":"C"},{"numero":52,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"Entre as condições clínicas necessárias para a administração de quimioterápicos está","alternativas":["leucócitos > 4.000/mm3.","neutrófilos < 2.000/mm3.","plaquetas > 100.000/mm3.","hemoglobina > 8g/dL.","ureia < 1,7mg/dL"],"correta":"A"},{"numero":54,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"O Programa de Volta para Casa é uma política de inclusão social destinada às p essoas com sofrimento psíquico, egressas de internação de longa permanência em hospitais psiquiátricos e de custódia. Esse programa faz parte do seguinte componente da Rede de Atenção Psicossocial:","alternativas":["Reabilitação Psicossocial.","Atenção Básica em Saúde.","Atenção psicossocial especializada.","Estratégia de desinstitucionalização.","Atenção residencial de caráter transitório"],"correta":"D"},{"numero":55,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Durante o exame físico um paciente apresentou pulso caracterizado pela diminuição da amplitude das pulsaç ões durante a inspiração forçada. Esse pulso é denominado","alternativas":["filiforme.","dicrótico.","bigeminado.","alternante.","paradoxal"],"correta":"E"},{"numero":56,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"Uma criança com paralisia cerebral apresentou marcha atáxica. Nesse tipo de marcha o paciente","alternativas":["Acentua a lordose lombar e inclina o tronco ora para a direita, ora para a esquerda.","Levanta acentuadamente o membro inferior para evitar tropeçar, lembrando o passo do ganso.","Apresenta perda de equilíbrio e de coordenação com tendência a ampliação da base de sustentação.","Apresenta um padrão de circundução do membro inferior plégico para fora e para frente.","Apresenta movimentos irregulares, espasmódicos e involuntários em todas as extremidades."],"correta":"C"},{"numero":57,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um paciente adulto deu entrada na Unidade de Pronto Atendimento apresentando crise convulsiva repetida sem a recuperação completa da consciência entre os episódios; glicemia capilar = 68mg/dL; frequência respiratória = 10irpm; e frequência cardíaca = 40bpm. Nesse caso, considera ndo o protocolo de classificação de risco do Ministério da Saúde, esse paciente deve ser classificado com a cor","alternativas":["azul.","verde.","amarela.","laranja.","vermelha"],"correta":"E"},{"numero":58,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"De acordo com o Protocolo do Ministério da Saúde, uma criança com anemia por deficiência de ferro apresenta algumas alterações nos exames laboratoriais. Entre os valores que determinam esse diagnóstico está","alternativas":["Hemoglobina < 11g/dL.","Ferritina < 40ng/mL.","Hematócrito < 50%.","Hemácias < 5,5 milhões/µL.","Eritrócitos < 6,1 milhões/µL"],"correta":"A"},{"numero":59,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"O tempo máximo que cada órgão resiste à falta de circulação e oxigenação sanguínea é denominado tempo de isquemia, sendo fundamental para a efetivação do transplante. De acordo com as orientações do Ministér io da Saúde, o tempo máximo de isquemia do rim é de","alternativas":["seis horas.","oito horas.","doze horas.","vinte e quatro horas.","quarenta e oito horas"],"correta":"E"},{"numero":60,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"De acordo com os níveis de avaliação na acreditação hospitalar, as Práticas de Gestão e Qualidade são parte dos princípios do","alternativas":["nível de avaliação 1.","nível de avaliação 2.","nível de avaliação 3.","nível de avaliação 4.","nível de avaliação 5"],"correta":"C"},{"numero":61,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Considerando as recomendações do Ministério da Saúde acerca dos acidentes de trabalho com exposição a material biológico, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A exposição percutânea e cutânea com pele não integra são consideradas exposição de risco para transmissão do HIV, Hepatite B e Hepatite C. ( ) A primeira dose da Profilaxia Pós Exposição ao HIV - PEP deve ser administrada idealmente em até 4h após o acidente ou, no máximo, em até de 48h. ( ) Qualquer acidente de trabalho com exposição a material biológico deve ser notificado em até 24h após a ocorrência. As afirmativas são, respectivamente,","alternativas":["F – V – F.","V – F – F.","F – F – F.","V – V – V.","F – V – V"],"correta":"B"},{"numero":62,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"De acordo com as medidas de prevenção de infecção recomendadas pela ANVISA, a antibioticoprofilaxia para parto vaginal é indicada somente em algumas situações especificas, sendo uma delas a de","alternativas":["trabalho de parto prematuro.","remoção manual da placenta.","lacerações de períneo de 1º grau.","lacerações de períneo de 2º grau.","trabalho de parto superior a 8h"],"correta":"B"},{"numero":63,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Os componentes da tríade de Virchow correspondem a fatores que potencializam ou predispõem ao risco de desenvolver fenômenos tromboembólicos venosos. Nesse sentido, assinale a opção que indica o fa tor de risco relacionado ao componente lesão do endotélio.","alternativas":["Varizes.","Gravidez.","Tabagismo.","Obesidade.","Reposição hormonal"],"correta":"C"},{"numero":64,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"O método de rastreamento do câncer do colo do útero (exame de Papanicolau) deve ser oferecido às mulheres ou qualquer pessoa com colo do útero que já teve atividade sexual e encontra -se na faixa etária de","alternativas":["18 a 45 anos.","20 a 50 anos.","25 a 64 anos.","30 a 66 anos.","35 a 64 anos."],"correta":"C"},{"numero":65,"disciplina":"Enfermagem","assunto":"Ética e Legislação em Enfermagem","enunciado":"Com base no Código de Ética dos Profissionais de Enfermagem, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) A advertência verbal consiste na repreensão que será divulgada nas publicações oficiais do Sistema dos Conselhos de Enfermagem e em jornais de grande circulação. ( ) Um profissional de enfermagem que promover ou participar de prática destinada a antecipar a morte do paciente, está sujeito à pena de cassação do direito ao exercício profissional. ( ) Uma das circunstancias consideradas a gravantes na aplicação da penalidade ao profissional de enfermagem, é o cometimento de infração por motivo fútil ou torpe. As afirmativas são, respectivamente,","alternativas":["V – V – F.","F – V – F.","V – V – V.","F – V – V.","V – F – V. LEGISLAÇÃO INSTITUCIONAL"],"correta":"D"}]},{"codigo":"aleto-2024-tecnico","ano":2024,"orgao":"Assembleia Legislativa do Estado do Tocantins","cargo":"Técnico Legislativo — Técnico em Enfermagem, Tipo 1","urlProva":"https://conhecimento.fgv.br/sites/default/files/concursos/tecnico-legislativo-tecnico-em-enfermagemcnm206-tipo-1.pdf","urlGabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitivo-policial-legislativo-ii-tecnico-legislativo-e-analista-legislativo_dsa1c.pdf","itens":[{"numero":1,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Leia o seguinte texto de um jornal de outros tempos: “Mudança nas moedas. A partir de junho começam a entrar em circulação as moedas de Cr$100 e Cr$500 subs tituindo as cédulas que trazem estampadas a poetisa Cecília Meireles e o naturalista Augusto Ruschi, respectivamente. O lançamento das moedas foi aprovado na reunião de ontem do Conselho Monetário Nacional, colocando fim à família de notas criadas no governo Sarney, sob a égide dos cruzados novos.” Sobre esse fragmento textual, analise as observações a seguir, feitas por um estudioso de nossa Língua, e assinale a correta.","alternativas":["“Começam a entrar em circulação” é bastante estranho, porque as moedas, pequenas que são e de pequeno valor, “entram” logo.","“trazem estampadas a poetisa Cecília Meireles e o naturalista Augusto Ruschi”, mas eu pensava que as moedas trazem estampadas as efígies de Fulano ou Beltrano.","“colocando fim à família” mostra o emprego inadequado de “colocar” em lugar de “pôr”.","“criadas”, por questão de clareza e precisão, devia ser substituído por “lançadas” ou “emitidas”.","“sob”, por questão de correção gramatical, deve ser substituído por “sobre”"],"correta":"B"},{"numero":2,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Leia o fragmento a seguir. “Não somos daqueles que só em meio aos livros, estimulados por livros vêm a ter pensamentos – é nosso hábito pensar ao ar livre, andando, saltando, escalando, dançando, preferivelmente em montes solitários ou próximos ao mar, onde mesmo as t rilhas se tornam pensativas.” (Nietzsche, filósofo alemão). Sobre o significado desse fragmento, assinale a afirmativa correta.","alternativas":["A leitura é importante para a criação de ideias originais.","As formas de gerúndio mostram a evolução cronológica das ações narradas pelo escritor.","O pronome relativo “onde” refere-se a locais ao ar livre.","A forma do verbo “tornar -se”, como verbo de ligação, indica um estado transitório.","Os ambientes solitários propiciam reflexões de valor"],"correta":"E"},{"numero":3,"disciplina":"Língua Portuguesa","assunto":"Coesão e Coerência","enunciado":"As citações a seguir são compostas por dois segmentos; assinale a opção em que a relação lógica indicada pelo segundo segmento está correta.","alternativas":["Dize-me o que crês ser / e te direi o que não és. – relação de oposição.","Quem crê é forte / quem duvida é fr aco. – relação de conclusão.","Seja lá por que um homem reza, / ele reza por um milagre. – relação de explicação.","Não adianta esperar que o navio chegue / se você não o mandou para lugar nenhum. – relação de causa.","Pense como um homem de ação / e aja como um pensador. – relação de conclusão"],"correta":"C"},{"numero":5,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"As frases a seguir mostram termos repetidos; assinale a opção que apresenta a frase em que o significado dos dois termos não é o mesmo.","alternativas":["Morrer é mudar de corpo como o ator muda de roupa.","Janeiro é o mês que se fazem bons votos aos amigos; os outros são os meses em que esses votos não se concretizam.","Quem tempo espera, muito tempo consome.","A falsidade da História é tão velha como a própria História.","Viva todos os dias como se fosse o último. Um dia você acerta"],"correta":"E"},{"numero":7,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"As frases a seguir mostram uma locução adjetiva introduzida pela preposição sem; assinale a opção em que a substituição dessa locução por um adjetivo de valor equivalente foi feita de forma adequada.","alternativas":["Cartas sem autoria declarada são sempre mal recebidas / desautorizadas.","Os poços sem água são de pouca serventia para a lavoura / áridos.","Foram deixados muitos problemas sem solução / insolúveis.","O governo tomou muitas atitudes sem nexo / desconexas.","Com os fogos de artifício, o campo ficou sem visão / invisível."],"correta":"C"},{"numero":9,"disciplina":"Língua Portuguesa","assunto":"Classes de Palavras","enunciado":"As perguntas a seguir apresentam o pronome pessoal oblíquo em ênclise (após o verbo); assinale a que mostra formulação incorreta, porque só admite próclise.","alternativas":["Os dois bandidos evadiram-se do presídio em Mossoró?","Onde podemos vê-los?","Eles dedicar-se-iam às tarefas com prazer.","Numa entrevista como esta, isto pergunta-se?","Quem dir-me-á tantas barbaridades, senão ele?"],"correta":"E"},{"numero":10,"disciplina":"Língua Portuguesa","assunto":"Ortografia e Acentuação","enunciado":"Assinale a opção que apresenta as duas palavras que devem ser grafadas com es e não com ex.","alternativas":["Excremento / expurgo.","Excusar / expontâneo.","Excomungar / expressar.","Extirpar / extorquir.","Exterminar / extremoso. Raciocínio Lógico Matemático"],"correta":"B"},{"numero":11,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Probabilidade","enunciado":"Dois números diferentes serão escolhidos ao acaso entre os elementos do conjunto {5,7,9,11,14}. A soma dos números escolhidos","alternativas":["certamente é ímpar.","certamente é par.","pode ser 26.","pode ser 18.","pode ser menor que 12"],"correta":"D"},{"numero":12,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Razão, Proporção e Porcentagem","enunciado":"Em um jogo, duas fichas azuis têm o mesmo valor de cinco fichas vermelhas e uma ficha preta vale o mesmo que três fichas azuis. Assim, duas fichas pretas equivalem a","alternativas":["sete fichas vermelhas.","oito fichas vermelhas.","nove fichas vermelhas.","doze fichas vermelhas.","quinze fichas vermelhas"],"correta":"E"},{"numero":13,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Razão, Proporção e Porcentagem","enunciado":"Sabe-se que 20% de N é igual a 13,4. Logo, 90% de N é igual a","alternativas":["59,6.","60,3.","61,2.","62,5.","63,2"],"correta":"B"},{"numero":14,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Argumentação Lógica","enunciado":"Marcelo é filho de Alberto. Pedro é filho de Luiz. Se Marcelo e Luiz são irmãos por parte de pai, então","alternativas":["Alberto é pai de Pedro.","Alberto é tio de Pedro.","Pedro é irmão de Marcelo.","Pedro é sobrinho de Marcelo.","Pedro é neto de Marcelo"],"correta":"D"},{"numero":15,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Sequências e Padrões","enunciado":"A seguir, s ão apresentados os 9 primeiros termos de uma sequência infinita de números inteiros. 13 , 12 , 14 , 11 , 15 , 10 , 16 , 9 , 17 , ... Os termos são, alternadamente, maiores e menores que seus antecessores imediatos, seguindo um padrão de construção. Sabendo-se que esse padrão é mantido ao longo de toda a sequência, conclui -se que um termo negativo aparecerá pela primeira vez na","alternativas":["28ª posição.","27ª posição.","26ª posição.","15ª posição.","14ª posição"],"correta":"A"},{"numero":16,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Regra de Três e Problemas Aritméticos","enunciado":"Para pagar um lanche, Temístocles usou uma nota de R$20,00 e recebeu, de troco, uma nota de R$5,00, duas notas de R$2,00, nove moedas de R$0,50 e 3 moedas de R$0,25. O lanche custou a Temístocles","alternativas":["R$5,25.","R$5,75.","R$6,25.","R$6,75.","R$7,25"],"correta":"B"},{"numero":17,"disciplina":"Raciocínio Lógico e Matemática","assunto":"Sequências e Padrões","enunciado":"Ana trabalha em sistema de home-office, mas precisa comparecer ao escritório de sua empresa em intervalos regulares. Se Ana comparece ao escritório em determinado dia, ela precisa comparecer de novo três dias úteis depois, isto é, descontando - se os sábados e os domingos. Assim, se ela compareceu em uma quinta-feira, deverá voltar ao escritório na terça -feira da semana seguinte. Hoje é sexta-feira e Ana está no escritório; assim, a penúltima vez em que ela esteve lá, foi uma","alternativas":["segunda-feira.","terça-feira.","quarta-feira.","quinta-feira.","sexta-feira."],"correta":"D"},{"numero":19,"disciplina":"Informática","assunto":"Windows","enunciado":"No contexto dos sistemas operacionais Microsoft Windows, o Painel de Controle é uma área central para gerenciar as configurações do sistema, opções de personalização e outros. Considerando as versões superiores ao Windows 7, assinale a opção que não indica uma funcionalidade encontrada no painel de controle.","alternativas":["Backup e Restauração.","Relógio e Região.","Hardware e Sons.","Contas de Usuário.","Configuração de Registro Avançadas"],"correta":"E"},{"numero":20,"disciplina":"Informática","assunto":"Windows","enunciado":"Nos sistemas operacionais Microsoft Windows 10, o recurso “Executar” permite aos usuários abrir rapidamente programas, pastas, documentos e recursos do sistema, ao d igitar o caminho completo ou o nome do item. Assinale a opção que apresenta a combinação de teclas usada para abrir a caixa de diálogo “Executar”.","alternativas":["Windows + E","Windows + I","Windows + K","Windows + L","Windows + R"],"correta":"E"},{"numero":22,"disciplina":"Informática","assunto":"Microsoft Word","enunciado":"Sobre a inserção de tabelas no Microsoft Word 2019 em português, analise as afirmativas a seguir. I. As tabelas admitem diferentes estilos de borda, cores de preenchimento e fontes, para melhorar sua apresentação visual. II. Ao inserir uma tabela, é possível definir o número de linhas e colunas antes de criá -la, no entanto, não é possível alterar a estrutura após a inserção. III. As tabelas podem ser inseridas apenas no iníc io de um documento e não podem ser movidas para outras partes do texto. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","II e III, apenas.","I e III, apenas.","I, II e III"],"correta":"A"},{"numero":23,"disciplina":"Informática","assunto":"Microsoft Excel","enunciado":"Em uma planilha Microsoft Excel 2019 em português do Brasil, há um conjunto de dados com vendas listadas na coluna B. Por meio da funcionalidade de Formatação Condicional, a seguinte função pode ser usada para destacar os 10% dos principais valores de vendas com preenchimento verde:","alternativas":["PERCENTIL.","MAXIMO.","SOMASES.","CONT.SE.","ABS."],"correta":"A"},{"numero":24,"disciplina":"Informática","assunto":"Segurança da Informação","enunciado":"Em uma pequena empresa, durante uma tentativa de realizar uma manutenção de rotina nos servidores ao final do expediente, José, um funcionário recém -contratado, com pouca experiência em TI, desliga um servidor que está rodando um serviço de DHCP. No dia seguinte, os usuários começam a reportar problemas. Considerando que todas as estações de trabalho com sistema operacional Windows estavam utilizando o servidor DHCP, assinale a opção que indica o que os usuários reportaram.","alternativas":["As estações de trabalho não estão ligando, pois dependem do servidor DHCP.","Havia lentidão na conexão com a internet.","Perda de acesso à internet, enquanto o acesso à rede local entre as estações de trabalho permaneceu possível.","Interrupção do serviço de e-mail; os demais serviços funcionavam.","Impressão em rede local não funcionava, mas a internet estava acessível"],"correta":"C"},{"numero":25,"disciplina":"Informática","assunto":"Segurança da Informação","enunciado":"Os ataques de negação de serviço distribuídos, conhecidos como DDoS, representam uma ameaça significativa para a segurança da internet. Com base nesse contexto, assinale a afirmativa incorreta.","alternativas":["Em um ataque DDoS, os atacantes usam uma rede de computadores comprometidos, conhecidos como botnets.","Os ataques DDoS geralmente visam comprometer os dados, tornando-os inacessíveis, mesmo para usuários autorizados.","Os ataques DDoS podem causar interrupções significativas nos serviços online.","Embora não s eja usual, ataques DDoS já foram feitos a partir de dispositivos IoT comprometidos, como câmeras de segurança.","Os ataques de DDoS podem ter como alvo vários recursos de rede, incluindo servidores web, jogos online e infraestrutura de nuvem"],"correta":"B"},{"numero":26,"disciplina":"Informática","assunto":"Computação em Nuvem e Backup","enunciado":"No contexto da computação em nuvem e seus serviços, assinale a opção que corresponde ao conceito de elasticidade.","alternativas":["A capacidade de expandir ou reduzir dinamicamente seus recursos de acordo com a demanda.","A flexibilidade de implementação de serviços.","A capacidade de uma nuvem de suportar múltiplos usuários, simultaneamente.","A velocidade da conexão entre a nuvem e os dispositivos do usuário.","A confiabilidade dos serviços oferecidos pelo provedor de computação em nuvem. História e Geografia do Estado de Tocantins"],"correta":"A"},{"numero":31,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Um paciente adulto, atendido em uma unidade de saúde, queixou-se, entre outras coisas, de picos de febre intercalados com períodos de temperatura normal (o retorno à normalidade aconteceu pelo menos uma vez a cada 24 horas). Nesse caso, o paciente está apresentado febre","alternativas":["séptica.","sustentada.","intermitente.","remitente.","contínua"],"correta":"C"},{"numero":33,"disciplina":"Enfermagem","assunto":"Hipertensão Arterial","enunciado":"A diferença entre as pressões sistólica e diastólica, utilizada como marcador de rigidez arterial, é denominada","alternativas":["débito cardíaco.","volume sistólico.","pressão de pulso.","débito sistólico.","pressão arterial média"],"correta":"C"},{"numero":34,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Um paciente com hiperpneia apresenta uma respiração","alternativas":["lenta e profunda.","rápida e profunda.","lenta e superficial.","rápida e superficial.","irregular e superficial"],"correta":"B"},{"numero":35,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Assinale a opção que corresponde a uma cobertura que promove o debridamento enzimático.","alternativas":["Hidrogel.","Hidrocoloide.","Colagenase.","Carvão ativado.","Alginato de cálcio"],"correta":"C"},{"numero":36,"disciplina":"Enfermagem","assunto":"Diabetes Mellitus","enunciado":"Entre as insulinas e análogas de insulina apresentadas a seguir, assinale aquela de ação mais rápida","alternativas":["NPH.","lispro.","regular.","degludeca.","glargina 100."],"correta":"B"},{"numero":37,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"Uma criança vítima de queimaduras é considerada grande queimado quando apresenta Superfície Corporal Queimada – SCQ acima de","alternativas":["10%.","15%.","20%.","25%.","30%"],"correta":"E"},{"numero":38,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Os pacientes com Acidente Vascular Cerebral Isquêmico que receberam terapia trombolítica devem ter pressão arterial, oximetria de pulso e eletrocardiografia monitorados continuamente por, pelo menos,","alternativas":["6 horas após o procedimento.","8 horas após o procedimento.","10 horas após o procedimento.","12 horas após o procedimento.","24 horas após o procedimento"],"correta":"E"},{"numero":39,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"No atendimento inicial ao politraumatizado (XA BCDE do trauma) a letra B abrange a seguinte ação:","alternativas":["análise da respiração.","contenção de hemorragia.","prevenção da hipotermia.","análise do nível de consciência.","proteção da coluna cervical"],"correta":"A"},{"numero":40,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"Assinale a opção que corresponde a uma contraindicação absoluta para administração de medicamentos por hipodermóclise.","alternativas":["Disfagia.","Confusão mental.","Obstrução intestinal.","Demência avançada.","Trombocitopenia grave"],"correta":"E"},{"numero":41,"disciplina":"Enfermagem","assunto":"Tuberculose","enunciado":"A busca ativa do sintomático respiratório de tuberculose é uma das estratégias para diminuir a morbimortalidade e a proliferação da doença. Nesse caso o sintomático respiratório é definido como a pessoa com tosse por período igual ou superior a","alternativas":["uma semana de duração.","duas semanas de duração.","três semanas de duração.","quatro semanas de duração.","cinco semanas de duração"],"correta":"C"},{"numero":42,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"Um paciente foi atendido em uma unidade de saúde com sinais e sintomas de dengue. Nesse caso, um medicamento contraindicado para esse paciente, por aumentar a chance de sangramento, é","alternativas":["a dipirona.","o ibuprofeno.","a bromoprida.","a novalgina.","o paracetamol"],"correta":"B"},{"numero":43,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"Acerca da vacina contra a dengue disponibilizada pelo Ministério da Saúde, é correto afirmar que","alternativas":["o esquema é composto por duas doses da vacina.","o esquema é composto por três doses da vacina.","o intervalo mínimo entre as doses é de trinta dias.","o intervalo máximo entre as doses é de sessenta dias.","deve ser administrada exclusivamente pela via IM"],"correta":"A"},{"numero":44,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Durante a realização de um curativo em um paciente acamado foi observada a presença de lesão por pressão Estágio 2. Esse tipo de lesão apresenta a seguinte característica:","alternativas":["perda da pele em sua espessura total.","pele com eritema que não embranquece.","gordura visível com presença de epíbole.","exposição da derme com presença de bolha.","perda tissular com exposição direta da fáscia"],"correta":"D"},{"numero":45,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Considerando as normas acerca da coleta de materia l para exame, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Na coleta de sangue, os tubos sem aditivos devem ser usados antes dos tubos destinados aos testes de coagulação. ( ) A coleta de secreção uretral deve ser realizada, de preferência pela manhã, antes da primeira micção ou há pelo menos duas horas ou mais sem ter urinado. ( ) Se a amostra de coprocultura não for entregue no laboratório em uma hora, deve ser conservada em geladeira a 8 C por no máximo 24 horas. As afirmativas são, respectivamente,","alternativas":["V – V – V.","F – F – F.","V – F – V.","F – V – V.","V – V – F"],"correta":"E"},{"numero":46,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Considere um mapa de risco ambiental em que alguns setores de um serviço de saúde estão sinalizados com as c ores azul, verde, vermelho, e amarelo. Nesse caso, os riscos representados pelas cores são, respectivamente,","alternativas":["biológico, acidente, químico e físico.","físico, biológico, ergonômico e químico.","acidente, físico, químico e ergonômico.","químico, físico, acidente e biológico.","ergonômico, químico, físico e acidente."],"correta":"C"},{"numero":47,"disciplina":"Enfermagem","assunto":"Centro de Material e Esterilização (CME)","enunciado":"O teste Bowie & Dick é realizado para verificar a eficiência do processo de esterilização pelo vapor sob pressão. Acerca desse teste, analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Deve ser realizado antes do primeiro ciclo do dia e após o último ciclo. ( ) O teste deve ser acondicionado em uma carga de material cirúrgico, que deverá passar pelo ciclo completo de esterilização. ( ) A qualificação do teste se dá quando constatada mudança uniforme de coloração em toda a extensão da folha. As afirmativas são, respectivamente,","alternativas":["V – F – V.","F – F – V.","V – V – V.","F – F – F.","V – F – F"],"correta":"B"},{"numero":48,"disciplina":"Enfermagem","assunto":"Centro Cirúrgico","enunciado":"Com base no protocolo de Cirurgia Segura, o condutor da lista de verificação deverá confirmar se o paciente possui alguma alergia conhecida. Essa confirmação deve ocorrer antes da","alternativas":["incisão cirúrgica.","indução anestésica.","profilaxia antimicrobiana.","monitorização do paciente.","demarcação do sítio cirúrgico"],"correta":"B"},{"numero":49,"disciplina":"Enfermagem","assunto":"Ética e Legislação em Enfermagem","enunciado":"O código de Ética dos profissionais de enfermagem dispõe que a assistência de enfermagem deve ser prestada livre de danos decorrentes de imperícia, negligência ou imprudência. Nesse caso, assinale a ação que configura imperícia.","alternativas":["Administrar medicação na dose errada e na via errada.","Deixar de prestar socorro em situações de emergência.","Realizar um procedimento sem o conhecimento técnico.","Administrar medicação sem ter certeza da dose prescrita.","Realizar um procedimento sem o uso de EPIs adequados"],"correta":"C"},{"numero":50,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"O princípio do SUS orientado pelo respeito às necessidades, diversidades e especificidades de cada cidadão ou grupo social e que tem relação direta com os conceitos de igualdade e de justiça social é denominado","alternativas":["equidade.","integralidade.","universalidade.","descentralização.","hierarquização. PRINCÍPIOS DA ADMINISTRAÇÃO PÚBLICA"],"correta":"A"},{"numero":51,"disciplina":"Direito Administrativo","assunto":"Organização Administrativa","enunciado":"A Administração Direta é composta por órgãos e entidades que fazem parte da estrutura do Estado e operam diretamente sob a autoridade do poder público. Em contrapartida, a Administração Indireta inclui entidades com personalidade jurídica própria, mas vinculadas ao Estado. Enquant o a Administração Direta executa diretamente políticas públicas, a Indireta opera de forma mais especializada, muitas vezes em atividades empresariais. Assinale a opção que indica a entidade dotada de personalidade jurídica de direito privado, com patrimôn io próprio e capital exclusivo da União, criado por lei para a exploração de atividade econômica.","alternativas":["Autarquia.","Empresa pública.","Fundação pública.","Organização social.","Sociedade de economia mista"],"correta":"B"},{"numero":53,"disciplina":"Direito Administrativo","assunto":"Controle da Administração Pública","enunciado":"A Lei de Acesso à Informação (Lei nº 12.527/2011) garante ao cidadão o direito de obter informações públicas, promovendo a transparência e a accountability no setor público. Assinale a opção que apresenta a qualidade da informação que pode ser conhecida e utilizada por indivíduos, equipamentos ou sistemas autorizados.","alternativas":["Integridade.","Autenticidade.","Transparência.","Primariedade.","Disponibilidade"],"correta":"C"},{"numero":55,"disciplina":"Direito Administrativo","assunto":"Licitações e Contratos","enunciado":"De acordo com a Lei nº 14.133/2021, conhecida como Nova Lei de Licitações e Contratos Administrativos, o processo licitatório visa prevenir contratações com sobrepreço, preços manifestamente inexequíveis e superfaturamento na execução dos contratos. Com relação aos casos de superfaturamento em que há dano provocado ao patrimônio d a Administração, analise as afirmativas a seguir. I. Medição de quantidades superiores às efetivamente executadas ou fornecidas. II. Alterações no orçamento de obras e de serviços de engenharia que causem desequilíbrio econômico -financeiro do contrato em favor do contratante. III. Deficiência na execução de obras e de serviços de engenharia que resultem em diminuição da sua qualidade, vida útil ou insegurança. Está correto o que se afirma em","alternativas":["I, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III. LEGISLAÇÃO INSTITUCIONAL"],"correta":"A"}]}] as const;
export async function sincronizarFGVAletoMacae2024() {
 const usuario=await prisma.usuario.findFirst({orderBy:{id:"asc"},select:{id:true}});
 if(!usuario){console.warn("[aleto-macae-2024] Sem usuário de referência");return {inseridas:0,existentes:0,duplicadas:0};}
 const normalizar=(s:string)=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
 const anteriores=await prisma.questao.findMany({where:{fonte:FONTE_PROVAS_REAIS},select:{enunciado:true}});
 const conhecidos=new Set(anteriores.map(x=>normalizar(x.enunciado)));
 const disciplinas=new Map<string,number>();
 let inseridas=0,existentes=0,duplicadas=0;
 for(const lote of LOTES)for(const q of lote.itens){
  if(!q.enunciado.trim()||q.alternativas.length!==5||!["A","B","C","D","E"].includes(q.correta)||
     q.alternativas.some(x=>!x.trim())||new Set(q.alternativas.map(x=>x.trim().toLowerCase())).size!==5)
     throw new Error("[aleto-macae-2024] Questão inválida "+lote.codigo+"/"+q.numero);
  const origemId="fgv-"+lote.codigo+"-tipo1-q"+String(q.numero).padStart(2,"0");
  const existe=await prisma.questao.findFirst({where:{fonte:FONTE_PROVAS_REAIS,origemId},select:{id:true}});
  if(existe){existentes++;continue;}
  const hash=normalizar(q.enunciado);
  if(conhecidos.has(hash)){duplicadas++;continue;}
  let disciplinaId=disciplinas.get(q.disciplina);
  if(!disciplinaId){
    let d=await prisma.disciplina.findFirst({where:{usuarioId:usuario.id,nome:{equals:q.disciplina,mode:"insensitive"}},select:{id:true}});
    if(!d)d=await prisma.disciplina.create({data:{usuarioId:usuario.id,nome:q.disciplina},select:{id:true}});
    disciplinaId=d.id;disciplinas.set(q.disciplina,disciplinaId);
  }
  await prisma.questao.create({data:{
    usuarioId:usuario.id,disciplinaId,tema:q.assunto,fonte:FONTE_PROVAS_REAIS,origemId,
    enunciado:q.enunciado,dificuldade:"medio",banca:"FGV",ano:lote.ano,
    orgao:lote.orgao,cargo:lote.cargo,fonteUrl:lote.urlProva,
    explicacao:"FGV/"+lote.orgao+" ("+lote.ano+"), "+lote.cargo+", prova Tipo 1, questão "+q.numero+
      ". Gabarito definitivo: "+q.correta+". Caderno: "+lote.urlProva+" | Gabarito: "+lote.urlGabarito,
    alternativas:{create:q.alternativas.map((texto,i)=>({texto:"ABCDE"[i]+") "+texto,correta:"ABCDE"[i]===q.correta}))}
  }});
  conhecidos.add(hash);inseridas++;
 }
 console.log("[aleto-macae-2024] "+inseridas+" inseridas; "+existentes+" existentes; "+duplicadas+" duplicadas ignoradas.");
 return {inseridas,existentes,duplicadas};
}
